295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Override
297	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
298	        Owner owner = this.clinicService.findOwnerById(ownerId);
299	        if (owner != null) {
300	            Pet pet = owner.getPet(petId);
