307	
308	    /**
309	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
310	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
311	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
312	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
313	     *
314	     * @return the non-blank idempotency key, or {@code null} when none was supplied
315	     */
316	    private String idempotencyKey() {
317	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
318	            return null;
319	        }
320	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
321	        return isBlank(key) ? null : key.trim();
322	    }
323	
324	    /**
325	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
326	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
327	     * the request body already rejects null and empty values, but permits whitespace-only strings
328	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
329	     * that gap so every required field must carry a non-blank value.
330	     *
331	     * @param ownerFieldsDto the submitted owner fields
332	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
333	     */
334	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
335	        List<String> missing = new ArrayList<>();
336	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
337	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
338	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
339	            missing.add("address");
340	        }
341	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
342	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
343	        if (!missing.isEmpty()) {
344	            throw new InvalidOwnerFieldsException(missing);
345	        }
346	    }
347	
348	    /**
349	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
350	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
351	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
352	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
353	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
354	     * {@link PostcodeValidator}.
355	     *
356	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
357	     *                       {@link #rejectBlankOwnerFields} having already run)
358	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
359	     */
360	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
361	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
362	            throw new InvalidOwnerFieldsException(List.of("postcode"));
363	        }
364	    }
365	
366	    private void addIfBlank(List<String> missing, String fieldName, String value) {
367	        if (isBlank(value)) {
368	            missing.add(fieldName);
369	        }
370	    }
371	
372	    private boolean isBlank(String value) {
373	        return value == null || value.isBlank();
374	    }
375	
376	    /**
377	     * Normalizes the submitted address on create to its canonical form (see
378	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
379	     * stored and returned, and the form every later address comparison (the required-field check,
380	     * household duplicate detection and the shared household id) is judged on. The structured fields
381	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
382	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
383	     * derived from them when a structured {@code addressLine1} is present, falling back to the
384	     * normalized flat {@code address} otherwise. Any absent field is left absent so
385	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
386	     * after normalization likewise reduces to the empty string and is rejected there.
387	     *
388	     * @param ownerFieldsDto the submitted owner fields
389	     */
390	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
391	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
392	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
393	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
394	        ownerFieldsDto.setAddressLine1(addressLine1);
395	        ownerFieldsDto.setAddressLine2(addressLine2);
396	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
397	    }
398	
399	    /**
400	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
401	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
402	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
403	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
404	     * is the single value every later reader of the address (the required-field check, household
405	     * duplicate detection and the shared household id) is judged on.
406	     *
407	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
408	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
409	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
410	     * @return the composed flat address, or {@code null} when no address form was supplied
411	     */
412	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
413	        if (isBlank(addressLine1)) {
414	            return flatAddress;
415	        }
416	        if (isBlank(addressLine2)) {
417	            return addressLine1;
418	        }
419	        return addressLine1 + " " + addressLine2;
420	    }
421	
422	    /**
423	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
424	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
425	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
426	     * {@code 400 Bad Request}.
427	     *
428	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
429	     *                       {@link #rejectBlankOwnerFields} having already run)
430	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
431	     */
432	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
433	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
434	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
435	        ownerFieldsDto.setTelephone(normalized);
436	    }
437	
438	    /**
439	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
440	     * untouched (email is optional). When present it is reduced to its canonical form (see
441	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
442	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
443	     *
444	     * @param ownerFieldsDto the submitted owner fields
445	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
446	     *                                     or its domain is on the disposable-domain blocklist
447	     */
448	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
449	        String email = ownerFieldsDto.getEmail();
450	        if (email == null || email.isBlank()) {
451	            return;
452	        }
453	        String normalized = EmailNormalizer.normalize(email)
454	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
455	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
456	            throw new InvalidOwnerFieldsException(List.of("email"));
457	        }
458	        ownerFieldsDto.setEmail(normalized);
459	    }
460	
461	    /**
462	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
463	     * duplicate detection is now expressed through the single derived {@code identityKey}
464	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
465	     * which replaces the previously separate telephone, email and household checks. Two owners denote
466	     * the same person when their identities collide on the telephone - the identity's distinguishing
467	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
468	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
469	     * same household with different telephones have different identities and are both allowed; an email
470	     * or a household on its own no longer makes a duplicate.
471	     *
472	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
473	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
474	     * @param householdId    the household id derived for the owner being created (see
475	     *                       {@link HouseholdNormalizer#toHouseholdId})
476	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
477	     */
478	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
479	        String identityKey = OwnerIdentity.identityKey(
480	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
481	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
482	        boolean inUse = this.clinicService.findAllOwners().stream()
483	            .filter(existing -> !existing.isDeleted())
484	            .map(Owner::getTelephone)
485	            .filter(Objects::nonNull)
486	            .map(TelephoneNormalizer::toComparisonKey)
487	            .anyMatch(telephoneKey::equals);
488	        if (inUse) {
489	            throw new DuplicateOwnerIdentityException(identityKey);
490	        }
491	    }
492	
493	    /**
494	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
495	     * both match the submitted values, compared case-insensitively. The count reflects only owners
496	     * already persisted at the time of the create, so the owner being created is never included.
497	     *
498	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
499	     *                  having already run)
500	     * @param lastName  the submitted last name (non-blank here)
501	     * @return the number of existing owners sharing the same first and last name
502	     */
503	    private int countNamesakes(String firstName, String lastName) {
504	        return (int) this.clinicService.findAllOwners().stream()
505	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
506	                && lastName.equalsIgnoreCase(owner.getLastName()))
507	            .count();
508	    }
509	
510	    /**
511	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
512	     * whose stored {@code householdId} equals the value derived for the owner being created. The
513	     * count reflects only owners already persisted at the time of the create, so the owner being
514	     * created is never included; callers add one to obtain the household size after this create.
515	     *
516	     * @param householdId the household identifier derived for the owner being created (see
517	     *                    {@link HouseholdNormalizer#toHouseholdId})
518	     * @return the number of existing owners already sharing that household
519	     */
520	    private int countHouseholdMembers(String householdId) {
521	        return householdMembers(householdId).size();
522	    }
523	
524	    /**
525	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
526	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
527	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
528	     * created is never among them.
529	     *
530	     * @param householdId the household identifier derived for the owner being created (see
531	     *                    {@link HouseholdNormalizer#toHouseholdId})
532	     * @return the existing owners already sharing that household (empty when {@code householdId} is
533	     *         {@code null})
534	     */
535	    private List<Owner> householdMembers(String householdId) {
536	        if (householdId == null) {
537	            return List.of();
538	        }
539	        return this.clinicService.findAllOwners().stream()
540	            .filter(member -> householdId.equals(member.getHouseholdId()))
541	            .toList();
542	    }
543	
544	    /**
545	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
546	     * {@code membershipLevel} among their existing household members. The owner's own level is the
547	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
548	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
549	     * owner's own level is returned unchanged.
550	     *
551	     * @param owner the owner being created, already stamped with its household id and size
552	     * @return the (possibly capped) membership level to stamp on the owner
553	     */
554	    private int cappedMembershipLevel(Owner owner) {
555	        int ownLevel = this.ownerMapper.membershipLevel(owner);
556	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
557	            .mapToInt(this.ownerMapper::membershipLevel)
558	            .max();
559	        return maxHouseholdLevel.isPresent()
560	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
561	            : ownLevel;
562	    }
563	
564	    /**
565	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
566	     * owner with an address taken from the request, so routing that through this single method keeps the
567	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
568	     * household id.
569	     *
570	     * @param ownerFieldsDto the submitted owner fields
571	     * @return the address to store on the owner
572	     */
573	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
574	        return ownerFieldsDto.getAddress();
575	    }
576	
577	    /**
578	     * Derives the household id an owner should carry from its submitted fields (see
579	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
580	     * household id, so routing them through this single method keeps them agreed on which of the
581	     * owner's fields key the household.
582	     *
583	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
584	     *                       {@link #rejectBlankOwnerFields} having already run on create)
585	     * @return the owner's household id
586	     */
587	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
588	        return HouseholdNormalizer.toHouseholdId(
589	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
590	    }
591	
592	    /**
593	     * Rejects creating an owner that would join an existing household as an indistinguishable
594	     * near-duplicate without declaring itself a member. The household is keyed on (last name,
595	     * postcode) through the derived {@code householdId} (see {@link HouseholdNormalizer#toHouseholdId}),
596	     * so a second owner sharing an existing owner's last name and postcode denotes the same household.
597	     * A genuinely distinct household member is told apart by its telephone: an owner whose normalized
598	     * telephone differs from every existing member's is a legitimate additional member (recorded as a
599	     * {@linkplain #findPossibleDuplicate possible duplicate}, not rejected). Only a create that shares
600	     * both the household and an existing member's telephone is reported as a {@code 409 Conflict},
601	     * unless it opts in with {@code sharesHousehold}, in which case it is accepted as a declared
602	     * household member. Only owners already persisted (before this create) are considered.
603	     *
604	     * @param ownerFieldsDto  the submitted owner fields (telephone already normalized)
605	     * @param householdId     the household id derived for the owner being created
606	     * @param sharesHousehold whether the request opted in to sharing a household
607	     * @throws DuplicateOwnerHouseholdException if an existing member shares the household and telephone
608	     *                                          and the request did not opt in with {@code sharesHousehold}
609	     */
610	    private void rejectHouseholdDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId,
611	            boolean sharesHousehold) {
612	        if (sharesHousehold || householdId == null) {
613	            return;
614	        }
615	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
616	        boolean indistinguishableMember = this.clinicService.findAllOwners().stream()
617	            .filter(existing -> !existing.isDeleted())
618	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
619	            .filter(existing -> existing.getTelephone() != null)
620	            .anyMatch(existing -> telephoneKey.equals(
621	                TelephoneNormalizer.toComparisonKey(existing.getTelephone())));
622	        if (indistinguishableMember) {
623	            throw new DuplicateOwnerHouseholdException(householdId);
624	        }
625	    }
626	
627	    /**
628	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
629	     * is none. The create has already cleared the hard-duplicate identity check
630	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
631	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
632	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
633	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
634	     * original record; owners with no postcode never match, since a shared postcode is required.
635	     *
636	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
637	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
638	     *         duplicate
639	     */
640	    private Integer findPossibleDuplicate(Owner owner) {
641	        String postcode = owner.getPostcode();
642	        if (postcode == null) {
643	            return null;
644	        }
645	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
646	        return this.clinicService.findAllOwners().stream()
647	            .filter(existing -> !existing.isDeleted())
648	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
649	            .filter(existing -> postcode.equals(existing.getPostcode()))
650	            .filter(existing -> existing.getTelephone() != null
651	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
652	            .map(Owner::getId)
653	            .filter(Objects::nonNull)
654	            .min(Integer::compareTo)
655	            .orElse(null);
656	    }
657	
658	    /**
659	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
660	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
661	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
662	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
663	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
664	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
665	     * duplicate, so it is never flagged.
666	     *
667	     * @param owner           the owner being created, with telephone already normalized and
668	     *                        lastName/postcode set
669	     * @param sharesHousehold whether the request opted in to sharing a household
670	     */
671	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
672	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
673	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
674	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
675	    }
676	
677	    /**
678	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
679	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
680	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
681	     *
682	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
683	     *             run)
684	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
685	     */
686	    private void rejectCityAtCapacity(String city) {
687	        long ownersInCity = this.clinicService.findAllOwners().stream()
688	            .map(Owner::getCity)
689	            .filter(Objects::nonNull)
690	            .filter(city::equalsIgnoreCase)
691	            .count();
692	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
693	            throw new OwnerCityAtCapacityException(city);
694	        }
695	    }
696	
697	    /**
698	     * Resolves the effective registration date for a create, rolled onto a business day. The
699	     * supplied date is used when present, otherwise the server's current date; either way the result
700	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
701	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
702	     * stored {@code registrationDate}, the membership number's year segment and the daily
703	     * create-limit's per-day count - is judged on this adjusted date.
704	     *
705	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
706	     *                                 default to the server's current date
707	     * @return the effective registration date, guaranteed to fall on a business day
708	     */
709	    /**
710	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
711	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
712	     * adjustment; a future date cannot describe a registration that has already happened, so it is
713	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
714	     * server's current date) and any date on or before today are accepted.
715	     *
716	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
717	     *                                 omitted
718	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
719	     */
720	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
721	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
722	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
723	        }
724	    }
725	
726	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
727	        LocalDate registrationDate =
728	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
729	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
730	    }
731	
732	    /**
733	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
734	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
735	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
736	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
737	     * Too Many Requests}.
738	     *
739	     * @param registrationDate   the create's effective registration date, already rolled onto a
740	     *                           business day by {@link #effectiveRegistrationDate}
741	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
742	     *                           {@code registrationDate} equals {@code registrationDate}
743	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
744	     *                                              owner registrations
745	     */
746	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
747	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
748	            throw new OwnerDailyRegistrationLimitException(registrationDate);
749	        }
750	    }
751	
752	    /**
753	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
754	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
755	     * bulk-signup warning are judged on.
756	     *
757	     * @param registrationDate the create's effective registration date, already rolled onto a business
758	     *                         day by {@link #effectiveRegistrationDate}
759	     * @return the number of existing owners registered on that day
760	     */
761	    private long countRegisteredOn(LocalDate registrationDate) {
762	        return this.clinicService.findAllOwners().stream()
763	            .map(Owner::getRegistrationDate)
764	            .filter(registrationDate::equals)
765	            .count();
766	    }
767	}
