47	
48	    /**
49	     * The key used to decide whether two owners belong to the same household: their normalized
50	     * {@code lastName} and {@code postcode} joined together, so households stored in different letter
51	     * cases or with incidental whitespace still compare equal.
52	     *
53	     * @param lastName the owner's last name (non-null)
54	     * @param postcode the owner's postcode, or null when absent
55	     * @return the comparison key
56	     */
57	    public static String toComparisonKey(String lastName, String postcode) {
58	        return normalizeField(lastName) + KEY_SEPARATOR + (postcode == null ? "" : postcode);
59	    }
60	
61	    /**
