34	 * 10). Two telephones denote the same number when their
35	 * {@linkplain #toComparisonKey(String) comparison keys} — their E.164 forms — are equal.
36	 */
37	public abstract class TelephoneNormalizer {
38	
39	    /** Characters stripped from a submitted telephone: spaces, dashes and brackets. */
40	    private static final String SEPARATORS = "[\\s()\\[\\]-]";
41	
42	    private static final int MIN_E164_DIGITS = 8;
43	
44	    private static final int MAX_E164_DIGITS = 15;
45	
46	    /**
47	     * The exact number of national (subscriber) digits required after each known country code.
48	     * A telephone whose country code appears here is accepted only when precisely this many
49	     * digits follow the code (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10).
50	     * Ordered longest-prefix-first so the country code is matched greedily.
51	     */
52	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = new LinkedHashMap<>();
53	
54	    static {
55	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("61", 9);
56	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("1", 10);
57	    }
